            "يمكن تنظيم الدروس عبر الإنترنت أو حضوريًا حسب العرض المقبول. تُحدَّد الأوقات والمواد والمستويات والمدد والطرائق في TutorSphere أو في ملحق.\n\nيجب إبلاغ المجموعة والأشخاص المعنيين في حال عدم التوفر.\n\n**الحد الأدنى لإشعار الإلغاء:** {{CANCELLATION_NOTICE}}\n**سماحية التأخر:** {{LATE_TOLERANCE}}\n**أثر الغياب غير المبرر:** {{UNJUSTIFIED_ABSENCE_RULE}}"),
        new("art8", "المادة 8 — المقابل المالي",
            "مقابل الخدمات المقدَّمة فعليًا والمصادَق عليها، يتلقى المدرّس:\n\n**السعر أو الصيغة:** {{COMPENSATION_RATE}}\n**العملة:** {{CURRENCY}}\n**وتيرة الدفع:** {{PAYMENT_FREQUENCY}}\n**وسيلة الدفع:** {{PAYMENT_METHOD}}\n**العمولات أو الرسوم:** {{APPLICABLE_FEES}}\n\nقد يُشترط الدفع بمصادقة الحضور وتقارير الدروس والعناصر الأخرى المطلوبة. تبقى الضرائب والرسوم المصرفية والالتزامات الضريبية الشخصية على عاتق المدرّس ما لم ينص القانون على خلاف ذلك.\n\nيجب تقديم أي اعتراض على دفعة خلال {{PAYMENT_DISPUTE_PERIOD}} يومًا."),
        new("art9", "المادة 9 — العلاقة مع التلاميذ وأولياء الأمور",
            "يجب استخدام وسائل التواصل المصرّح بها من المجموعة.\n\nخلال مدة العقد وخلال {{NON_SOLICITATION_PERIOD}} بعد انتهائه، يلتزم المدرّس، في الحدود التي يسمح بها القانون، بعدم تجاوز المنصة لتقديم خدمات مدفوعة مباشرة للتلاميذ أو الأسر الذين قدّمتهم المجموعة.\n\nلا تسري هذه المادة على العلاقات التي يستطيع المدرّس إثبات وجودها قبل انضمامه إلى المجموعة."),
        new("art10", "المادة 10 — السرية",
            "تُعد سرية كل المعلومات غير العلنية المتعلقة بالتلاميذ وأسرهم والمدرّسين وأعضاء المجموعة والطرائق التربوية والتعريفات والبيانات المالية والأنظمة التقنية والوثائق الداخلية واستراتيجيات المجموعة.\n\nلا يجوز إفشاؤها أو استخدامها خارج تنفيذ هذا العقد. يبقى هذا الالتزام قائمًا بعد انتهاء العقد."),
        new("art11", "المادة 11 — حماية البيانات الشخصية",
            "يلتزم المدرّس بمعالجة البيانات الشخصية الضرورية فقط لأداء خدماته، وحفظها بأمان، وعدم نسخها دون حاجة، وعدم نقلها إلى طرف غير مصرّح له، وحذفها أو إرجاعها في نهاية المهمة، والإبلاغ فورًا عن أي فقدان أو إفشاء أو استخدام غير مصرّح به.\n\nيجب معالجة البيانات وفق قوانين الخصوصية الواجبة التطبيق."),
        new("art12", "المادة 12 — تسجيل الدروس واستخدام الذكاء الاصطناعي",
            "لا يجوز تسجيل درس أو تفريغه أو تحليله بنظام ذكاء اصطناعي إلا إذا أذنت المجموعة بهذه الوظيفة وتم الحصول على الموافقات المطلوبة قانونًا.\n\nيُبلَّغ المدرّس قبل تفعيل التسجيل أو التحليل الآلي. لا تُستخدم التسجيلات والملخصات والتفريغات إلا للأغراض المصرّح بها."),
        new("art13", "المادة 13 — الملكية الفكرية",
            "يحتفظ المدرّس بملكية المحتويات التربوية التي أنشأها قبل هذا العقد. ويمنح المجموعة إذنًا غير حصري لاستخدام المحتويات التي يودعها على TutorSphere بالقدر اللازم لتقديم الخدمات ومتابعتها وأرشفتها.\n\nتعود المحتويات المنشأة خصيصًا والمدفوعة من المجموعة إلى: {{INTELLECTUAL_PROPERTY_RULE}}.\n\nيضمن المدرّس أنه يملك الحقوق اللازمة ويحترم حقوق المؤلف."),
        new("art14", "المادة 14 — التقييم ومراقبة الجودة",
            "يجوز للمجموعة تقييم الجودة انطلاقًا من تقارير الدروس واحترام المواعيد وتعليقات أولياء الأمور والتلاميذ والنتائج التربوية والحوادث المبلَّغ عنها وعمليات الامتثال المصرّح بها.\n\nيجوز للمدرّس الاطلاع على التقييمات المتعلقة به وتقديم ملاحظاته. عند وجود صعوبة، يجوز للمجموعة طلب تكوين أو خطة تحسين أو إجراء تعليق."),
        new("art15", "المادة 15 — المدة",
            "يُبرم هذا العقد: {{CONTRACT_DURATION_TYPE}}.\n\nويدخل حيّز النفاذ بتاريخ التوقيع الإلكتروني من الطرفين.\n\nإذا كان محدد المدة، ينتهي في {{CONTRACT_END_DATE}} ما لم يُجدَّد أو يُنهَ قبل ذلك."),
        new("art16", "المادة 16 — التعليق والإنهاء",
            "يجوز لكل طرف إنهاء العقد مع إشعار مدته {{TERMINATION_NOTICE}} يومًا.\n\nيجوز للمجموعة تعليق المدرّس فورًا في حال خطر على سلامة تلميذ، أو احتيال أو تصريح كاذب، أو انتهاك جسيم للسرية، أو سلوك مسيء أو تمييزي، أو إخلال متكرر بالمواعيد أو الالتزامات التربوية، أو استخدام غير مصرّح به للبيانات، أو إخلال جسيم بهذا العقد أو بالقانون.\n\nقبل الإنهاء النهائي، ينبغي عادة إبلاغ المدرّس بالأسباب وتمكينه من إبداء ملاحظاته، إلا في حالة طارئة تتعلق بالسلامة أو التزام قانوني."),
        new("art17", "المادة 17 — آثار انتهاء العقد",
            "عند انتهاء العقد، يجب على المدرّس إتمام التقارير المتبقية أو تسليمها، وإرجاع البيانات السرية أو حذفها، والتوقف عن استخدام موارد المجموعة وصلاحياتها، واحترام الالتزامات التي تبقى سارية.\n\nتبقى المبالغ المستحقة عن الخدمات المقدَّمة بصفة صحيحة واجبة الدفع."),
        new("art18", "المادة 18 — المسؤولية",
            "كل طرف مسؤول عن أفعاله وأخطائه وإهماله ومخالفاته للقانون. والمدرّس مسؤول عن الجودة المهنية لخدماته وعن الأضرار الناتجة عن خطأ أو إهمال جسيم أو سلوك عمدي.\n\nTutorSphere أداة تقنية للإدارة والتواصل. ولا تحل المنصة محل المسؤولية التربوية للمجموعة أو المدرّس.\n\nلا يقيّد أي حكم في هذا العقد مسؤولية لا يجوز استبعادها قانونًا."),
        new("art19", "المادة 19 — القوة القاهرة",
            "لا يُسأل أي طرف عن تأخير ناتج عن حدث خارج عن إرادته بصورة معقولة، ولا سيما كارثة أو عطل كبير أو نزاع أو قرار حكومي أو انقطاع واسع للاتصالات.\n\nيجب على الطرف المعني إبلاغ الطرف الآخر في أقرب وقت واتخاذ تدابير معقولة للحد من الآثار."),
        new("art20", "المادة 20 — تسوية النزاعات",
            "يلتزم الطرفان أولًا بالسعي إلى حل ودي. يجب تقديم أي مطالبة كتابةً وتتضمن الوقائع والعناصر الثبوتية والحل المطلوب.\n\nعند تعذّر الاتفاق خلال {{AMICABLE_RESOLUTION_PERIOD}} يومًا، يُعرض النزاع على: {{DISPUTE_RESOLUTION_METHOD}}."),
        new("art21", "المادة 21 — القانون الواجب التطبيق",
            "يخضع هذا العقد لقوانين: {{GOVERNING_JURISDICTION}}.\n\nوالمحاكم أو الهيئات المختصة هي محاكم: {{COMPETENT_COURT_LOCATION}}.\n\nتسري هذه المادة مع مراعاة القواعد الآمرة في بلد إقامة المدرّس أو مكان تنفيذ الخدمات."),
        new("art22", "المادة 22 — تعديل العقد",
            "يجب إبلاغ المدرّس بأي تعديل جوهري. عندما تتطلّب نسخة جديدة موافقته، يُرسل إليه عقد جديد أو ملحق للتوقيع.\n\nلا تحل النسخة الجديدة محل السابقة إلا بعد قبولها، ما لم يُجز القانون إجراءً آخر."),
        new("art23", "المادة 23 — شمولية العقد وقابلية التجزئة",
            "يمثّل هذا العقد وملاحقه كامل الاتفاق بين الطرفين بشأن موضوعه.\n\nإذا اعتُبر حكم باطلًا، تبقى الأحكام الأخرى سارية في الحدود التي يسمح بها القانون."),
        new("art24", "المادة 24 — التوقيع الإلكتروني",
            "يقرّ المدرّس بأنه تلقّى العقد بلغة يفهمها، وتمكّن من الاطلاع على الوثيقة كاملة، وتحقّق من دقة بياناته، وقبل كل شرط إلزامي، ووقّع بحرية إلكترونيًا، وحصل على نسخة موقّعة أو على إمكانية الوصول إليها.\n\nبعد التوقيع، يُنشئ النظام ملف PDF نهائيًا يتضمن الرقم الفريد والإصدار واللغة وتاريخ ووقت التوقيع وهوية الموقعين والبصمة الرقمية ورمز QR للتحقق وعناصر الإثبات المسجَّلة في سجل التدقيق."),
        new("annexes", "الملاحق",
            "تشكّل جزءًا لا يتجزأ من هذا العقد كما تظهر في TutorSphere:\n\n• الملحق أ — المواد والمستويات المدرَّسة\n• الملحق ب — التوافر والجداول\n• الملحق ج — المقابل المالي وطرائق الدفع\n• الملحق د — سياسة الإلغاء والغياب\n• الملحق هـ — مدونة السلوك وحماية الأطفال\n• الملحق و — سياسة السرية وحماية البيانات\n• الملحق ز — قواعد استخدام TutorSphere")
    ];
}
